function mockFetchOnce(body: unknown, status = 200, headers: Record<string, string> = {}) {
  global.fetch = vi.fn().mockResolvedValue({
    ok: status < 300,
    status,
    headers: { get: (k: string) => headers[k] ?? null },
    json: async () => body,
    text: async () => JSON.stringify(body),
    arrayBuffer: async () => new TextEncoder().encode(JSON.stringify(body)).buffer,
  }) as unknown as typeof fetch;
}

function calledUrl(): string {
  return (fetch as unknown as { mock: { calls: unknown[][] } }).mock.calls[0][0] as string;
}
function calledInit(): RequestInit | undefined {
  return (fetch as unknown as { mock: { calls: unknown[][] } }).mock.calls[0][1] as RequestInit | undefined;
}

describe("FE-1 server/onboarding — RM", () => {
  afterEach(() => vi.restoreAllMocks());

  it("fetchBoard() hits GET /api/rm/onboardings and returns the BoardDTO verbatim", async () => {
    mockFetchOnce(BOARD);
    const result = await fetchBoard();
    expect(calledUrl().endsWith(ENDPOINTS.RM.ONBOARDINGS)).toBe(true);
    expect(result).toEqual({ success: true, data: BOARD });
  });

  it("startOnboarding() POSTs the full StartOnboardingReq body", async () => {
    mockFetchOnce(ONBOARDING);
    const req = {
      client_name: "Jane Doe", email: "jane@example.com", primary_phone: "+852 1234 5678",
      address: "1 Main St", country_of_residence: "HK",
      id_type: "passport", id_number: "P123456",
      ibhk_account: "U-1000001", sw_account: "SW-2000001",
      model_id: "m-1", units: 5, mgmt_fee: 0.015, incentive_fee: 0.2,
      initial_cash_deposit: 5000000,
    };
    const result = await startOnboarding(req);
    expect(calledUrl().endsWith(ENDPOINTS.RM.ONBOARDINGS)).toBe(true);
    expect(calledInit()?.method).toBe("POST");
    expect(JSON.parse(calledInit()?.body as string)).toEqual(req);
    expect(result).toEqual({ success: true, data: ONBOARDING });
  });

  it("uploadDocument() posts via apiClientFormData (FormData body, not JSON)", async () => {
    mockFetchOnce(DOCUMENT);
    const fd = new FormData();
    fd.append("file", new Blob(["x"]), "passport.pdf");
    const result = await uploadDocument("ob-1", "passport", fd);
    expect(calledUrl().endsWith(ENDPOINTS.RM.ONBOARDING_DOC("ob-1", "passport"))).toBe(true);
    expect(calledInit()?.body).toBe(fd);
    expect(result).toEqual({ success: true, data: DOCUMENT });
  });

  it("submitAll() POSTs to the submit route and returns the updated OnboardingDTO", async () => {
    mockFetchOnce(ONBOARDING);
    const result = await submitAll("ob-1");
    expect(calledUrl().endsWith(ENDPOINTS.RM.ONBOARDING_SUBMIT("ob-1"))).toBe(true);
    expect(calledInit()?.method).toBe("POST");
    expect(result).toEqual({ success: true, data: ONBOARDING });
  });

  it("surfaces a 409 (submit blocked by an outstanding doc) as a failed APIResult with HTTP_409", async () => {
    mockFetchOnce({ detail: "required document missing" }, 409);
    const result = await submitAll("ob-1");
    expect(result.success).toBe(false);
    if (!result.success) expect(result.code).toBe("HTTP_409");
  });
});

describe("FE-1 server/onboarding — Compliance", () => {
  afterEach(() => vi.restoreAllMocks());

  it("fetchComplianceQueue() hits GET /api/compliance/onboardings and returns a flat OnboardingDTO[]", async () => {
    mockFetchOnce([ONBOARDING]);
    const result = await fetchComplianceQueue();
    expect(calledUrl().endsWith(ENDPOINTS.COMPLIANCE.ONBOARDINGS)).toBe(true);
    expect(result).toEqual({ success: true, data: [ONBOARDING] });
  });

  it("submitVerdict() POSTs {verdict, note} to the per-doc verdict route", async () => {
    mockFetchOnce(DOCUMENT);
    const result = await submitVerdict("ob-1", "passport", { verdict: "valid", note: null });
    expect(calledUrl().endsWith(ENDPOINTS.COMPLIANCE.ONBOARDING_VERDICT("ob-1", "passport"))).toBe(true);
    expect(JSON.parse(calledInit()?.body as string)).toEqual({ verdict: "valid", note: null });
    expect(result).toEqual({ success: true, data: DOCUMENT });
  });

  it("approveOnboarding() POSTs to the approve route", async () => {
    mockFetchOnce({ ...ONBOARDING, status: "active" });
    const result = await approveOnboarding("ob-1");
    expect(calledUrl().endsWith(ENDPOINTS.COMPLIANCE.ONBOARDING_APPROVE("ob-1"))).toBe(true);
    expect(calledInit()?.method).toBe("POST");
    expect(result.success).toBe(true);
  });

  it("rejectOnboarding() POSTs {reason} to the reject route", async () => {
    mockFetchOnce({ ...ONBOARDING, status: "pending_review" });
    const result = await rejectOnboarding("ob-1", { reason: "bad ID scan" });
    expect(calledUrl().endsWith(ENDPOINTS.COMPLIANCE.ONBOARDING_REJECT("ob-1"))).toBe(true);
    expect(JSON.parse(calledInit()?.body as string)).toEqual({ reason: "bad ID scan" });
    expect(result.success).toBe(true);
  });

  it("surfaces a 401 on approve as UNAUTHORIZED", async () => {
    mockFetchOnce({}, 401);
    const result = await approveOnboarding("ob-1");
    expect(result).toEqual({ success: false, error: "Unauthorized", code: "UNAUTHORIZED" });
  });

  it("downloadDocument() streams the file and base64-encodes it with the parsed filename/content-type", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: true,
      status: 200,
      headers: {
        get: (k: string) =>
          k === "Content-Disposition" ? 'attachment; filename="passport.pdf"' :
          k === "Content-Type" ? "application/pdf" : null,
      },
      arrayBuffer: async () => new TextEncoder().encode("%PDF-1.4").buffer,
    }) as unknown as typeof fetch;
    const result = await downloadDocument("ob-1", "passport");
    expect(calledUrl()).toContain(ENDPOINTS.COMPLIANCE.ONBOARDING_DOWNLOAD("ob-1", "passport"));
    expect(result).toEqual({
      success: true,
      data: { filename: "passport.pdf", contentType: "application/pdf", base64: expect.any(String) },
    });
  });

  it("downloadDocument() surfaces a non-2xx status as a failed APIResult", async () => {
    global.fetch = vi.fn().mockResolvedValue({
      ok: false,
      status: 404,
      headers: { get: () => null },
      arrayBuffer: async () => new ArrayBuffer(0),
    }) as unknown as typeof fetch;
    const result = await downloadDocument("ob-1", "missing-doc");
    expect(result).toEqual({ success: false, error: "HTTP 404", code: "HTTP_404" });
  });
});

